// Auto-generated: Livguard insert PDFs as base64
// DCR = 5 product pages, NonDCR = 5 product pages + certificate

function b64ToUint8(b64: string): Uint8Array {
  const binary = atob(b64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) {
    bytes[i] = binary.charCodeAt(i);
  }
  return bytes;
}

const DCR_B64 = "";

const NONDCR_B64 = "";

export function getInsertPdfBytes(type: "dcr" | "nonDcr"): Uint8Array {
  return b64ToUint8(type === "dcr" ? DCR_B64 : NONDCR_B64);
}
